      "代表制と直接参加、そして熟議という三つの考え方の長所と問題点を両面から説明せよ",
      "多数派の意思と少数派の権利が対立する場面、または専門知と民意が食い違う場面を一つ取り上げ、何をどう優先すべきか自分の立場を根拠とともに論じよ",
      "自分の立場に対して想定される反対意見を挙げ、それに応答せよ",
